17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Optional;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.BusinessDay;
31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.advice.RejectedRequestException;
35	import org.springframework.samples.petclinic.rest.api.OwnersApi;
36	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
37	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.PetDto;
39	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
42	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
43	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
44	import org.springframework.samples.petclinic.rest.validation.PostcodeValidator;
45	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
46	import org.springframework.samples.petclinic.service.ClinicService;
47	import org.springframework.samples.petclinic.service.OwnerAuditLogger;
48	import org.springframework.samples.petclinic.service.OwnerCreationIdempotencyStore;
49	import org.springframework.samples.petclinic.service.WelcomeNotifier;
50	import org.springframework.security.access.prepost.PreAuthorize;
51	import org.springframework.web.bind.annotation.CrossOrigin;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.util.UriComponentsBuilder;
55	
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /**
68	     * Maximum number of owners allowed to be registered in a single city. A new owner
69	     * whose city already holds this many owners is rejected as a conflict.
70	     */
71	    private static final long MAX_OWNERS_PER_CITY = 50;
72	
73	    /**
74	     * Maximum number of owners allowed to be registered in a single day. Once this many
75	     * owners already carry today's registration date, a further create is rejected as
76	     * too many requests.
77	     */
78	    private static final long MAX_OWNERS_PER_DAY = 100;
79	
80	    private final ClinicService clinicService;
81	
82	    private final OwnerMapper ownerMapper;
83	
84	    private final PetMapper petMapper;
85	
86	    private final VisitMapper visitMapper;
87	
88	    private final TelephoneNormalizer telephoneNormalizer;
89	
90	    private final EmailNormalizer emailNormalizer;
91	
92	    private final AddressNormalizer addressNormalizer;
93	
94	    private final PostcodeValidator postcodeValidator;
95	
96	    private final OwnerAuditLogger ownerAuditLogger;
97	
98	    private final OwnerCreationIdempotencyStore idempotencyStore;
99	
100	    private final WelcomeNotifier welcomeNotifier;
101	
102	    public OwnerRestControllerV1(ClinicService clinicService,
103	                                 OwnerMapper ownerMapper,
104	                                 PetMapper petMapper,
105	                                 VisitMapper visitMapper,
106	                                 TelephoneNormalizer telephoneNormalizer,
107	                                 EmailNormalizer emailNormalizer,
108	                                 AddressNormalizer addressNormalizer,
109	                                 PostcodeValidator postcodeValidator,
110	                                 OwnerAuditLogger ownerAuditLogger,
111	                                 OwnerCreationIdempotencyStore idempotencyStore,
112	                                 WelcomeNotifier welcomeNotifier) {
113	        this.clinicService = clinicService;
114	        this.ownerMapper = ownerMapper;
115	        this.petMapper = petMapper;
116	        this.visitMapper = visitMapper;
117	        this.telephoneNormalizer = telephoneNormalizer;
118	        this.emailNormalizer = emailNormalizer;
119	        this.addressNormalizer = addressNormalizer;
120	        this.postcodeValidator = postcodeValidator;
121	        this.ownerAuditLogger = ownerAuditLogger;
122	        this.idempotencyStore = idempotencyStore;
123	        this.welcomeNotifier = welcomeNotifier;
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
129	        Collection<Owner> owners;
130	        if (lastName != null) {
131	            owners = this.clinicService.findOwnerByLastName(lastName);
132	        } else {
133	            owners = this.clinicService.findAllOwners();
134	        }
135	        if (owners.isEmpty()) {
136	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
137	        }
138	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
144	        Owner owner = this.clinicService.findOwnerById(ownerId);
145	        if (owner == null) {
146	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
147	        }
148	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
149	    }
150	
151	    /**
152	     * Normalize the owner's supplied address into its canonical stored form, preferring
153	     * the structured fields over the flat address. When a non-blank {@code addressLine1}
154	     * is supplied it wins: both structured lines are normalized and the stored
155	     * {@code address} becomes their composed value; otherwise the flat {@code address} is
156	     * normalized and used. The owner is left with a normalized structured/flat address.
157	     *
158	     * @param owner the owner whose address fields are normalized in place
159	     * @return {@code true} if the owner supplies an address in either form, {@code false}
160	     * when neither a structured nor a flat address was given
161	     */
162	    private boolean normalizeAddress(Owner owner) {
163	        String addressLine1 = addressNormalizer.normalize(owner.getAddressLine1());
164	        String addressLine2 = addressNormalizer.normalize(owner.getAddressLine2());
165	        String flatAddress = addressNormalizer.normalize(owner.getAddress());
166	        owner.setAddressLine2(addressNormalizer.isBlank(addressLine2) ? null : addressLine2);
167	        if (!addressNormalizer.isBlank(addressLine1)) {
168	            owner.setAddressLine1(addressLine1);
169	            owner.setAddress(addressNormalizer.compose(addressLine1, addressLine2));
170	            return true;
171	        }
172	        owner.setAddressLine1(null);
173	        if (!addressNormalizer.isBlank(flatAddress)) {
174	            owner.setAddress(flatAddress);
175	            return true;
176	        }
177	        return false;
178	    }
179	
180	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
181	    @Override
182	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
183	        Owner replay = replayIdempotentCreate(idempotencyKey);
184	        if (replay != null) {
185	            return new ResponseEntity<>(ownerMapper.toOwnerDto(replay), HttpStatus.OK);
186	        }
187	        HttpHeaders headers = new HttpHeaders();
188	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
189	        if (!normalizeAddress(owner)) {
190	            throw new RejectedRequestException(HttpStatus.BAD_REQUEST,
191	                "An address must be supplied, either as a flat address or a structured address line 1");
192	        }
193	        Optional<String> e164Telephone = telephoneNormalizer.toE164(owner.getTelephone());
194	        if (e164Telephone.isEmpty()) {
195	            throw new RejectedRequestException(HttpStatus.BAD_REQUEST,
196	                "The supplied telephone number is not a valid phone number");
197	        }
198	        String telephone = e164Telephone.get();
199	        String email = emailNormalizer.normalize(owner.getEmail());
200	        if (email != null && (!emailNormalizer.isValid(email) || emailNormalizer.isDisposable(email))) {
201	            throw new RejectedRequestException(HttpStatus.BAD_REQUEST,
202	                "The supplied email address is invalid or from a disallowed domain");
203	        }
204	        if (owner.getPostcode() != null && !postcodeValidator.isValid(owner.getPostcode(), owner.getCity())) {
205	            throw new RejectedRequestException(HttpStatus.BAD_REQUEST,
206	                "The supplied postcode is not valid for the owner's city");
207	        }
208	        LocalDate suppliedRegistrationDate = owner.getRegistrationDate();
209	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
210	            throw new RejectedRequestException(HttpStatus.BAD_REQUEST,
211	                "The registration date cannot be in the future");
212	        }
213	        LocalDate registrationDate = BusinessDay.rollForward(
214	            suppliedRegistrationDate == null ? LocalDate.now() : suppliedRegistrationDate);
215	        owner.setRegistrationDate(registrationDate);
216	        if (clinicService.countOwnersByRegistrationDate(registrationDate) >= MAX_OWNERS_PER_DAY) {
217	            throw new RejectedRequestException(HttpStatus.TOO_MANY_REQUESTS,
218	                "The maximum number of owner registrations for this day has been reached");
219	        }
220	        owner.setTelephone(telephone);
221	        owner.setEmail(email);
222	        if (clinicService.countOwnersByCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
223	            throw new RejectedRequestException(HttpStatus.CONFLICT,
224	                "The maximum number of owners for this city has been reached");
225	        }
226	        // Reject a hard duplicate: an existing live owner sharing this owner's identity key
227	        // (its normalized telephone, email and phonetic last name). The email-domain blocklist
228	        // above is applied first, so a disposable-email duplicate is a 400, not a 409.
229	        if (clinicService.isDuplicateOwner(owner)) {
230	            throw new RejectedRequestException(HttpStatus.CONFLICT,
231	                "An owner with the same identity already exists");
232	        }
233	        // The household is keyed on (last name, postcode): a second owner sharing both joins
234	        // the existing household. Unless it declares 'sharesHousehold', it is recorded as a
235	        // possible duplicate of the sitting member (see saveOwner); a declared member joins as
236	        // a (non-suspected) household member instead. Either way its membership level is capped
237	        // relative to the household's existing members.
238	        owner.setDeclaredHouseholdMember(Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
239	        this.clinicService.saveOwner(owner);
240	        this.ownerAuditLogger.logCreated(owner);
241	        this.welcomeNotifier.welcome(owner);
242	        if (idempotencyKey != null) {
243	            this.idempotencyStore.remember(idempotencyKey, owner.getId());
244	        }
245	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
246	        headers.setLocation(UriComponentsBuilder.newInstance()
247	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
248	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
249	    }
250	
251	    /**
252	     * Look up the owner already created under the given {@code Idempotency-Key}, if any.
253	     * A repeated create carrying a key that has already produced an owner replays that
254	     * original owner instead of creating a duplicate.
255	     *
256	     * @param idempotencyKey the client-supplied idempotency key, or {@code null} when the
257	     *                       request carries no {@code Idempotency-Key} header
258	     * @return the originally created owner to replay, or {@code null} when the key is
259	     * absent, unseen, or its owner no longer exists
260	     */
261	    private Owner replayIdempotentCreate(String idempotencyKey) {
262	        if (idempotencyKey == null) {
263	            return null;
264	        }
265	        return idempotencyStore.findOwnerId(idempotencyKey)
266	            .map(clinicService::findOwnerById)
267	            .orElse(null);
268	    }
269	
270	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
271	    @Override
272	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
273	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
274	        if (currentOwner == null) {
275	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
276	        }
277	        Optional<String> e164Telephone = telephoneNormalizer.toE164(ownerFieldsDto.getTelephone());
278	        if (e164Telephone.isEmpty()) {
279	            throw new RejectedRequestException(HttpStatus.BAD_REQUEST,
280	                "The supplied telephone number is not a valid phone number");
281	        }
282	        String email = emailNormalizer.normalize(ownerFieldsDto.getEmail());
283	        if (email != null && (!emailNormalizer.isValid(email) || emailNormalizer.isDisposable(email))) {
284	            throw new RejectedRequestException(HttpStatus.BAD_REQUEST,
285	                "The supplied email address is invalid or from a disallowed domain");
286	        }
287	        String postcode = ownerFieldsDto.getPostcode();
288	        if (postcode != null && !postcodeValidator.isValid(postcode, ownerFieldsDto.getCity())) {
289	            throw new RejectedRequestException(HttpStatus.BAD_REQUEST,
290	                "The supplied postcode is not valid for the owner's city");
291	        }
292	        currentOwner.setAddress(ownerFieldsDto.getAddress());
293	        currentOwner.setCity(ownerFieldsDto.getCity());
294	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
295	        currentOwner.setLastName(ownerFieldsDto.getLastName());
296	        currentOwner.setTelephone(e164Telephone.get());
297	        currentOwner.setEmail(email);
298	        currentOwner.setPostcode(postcode);
299	        this.clinicService.saveOwner(currentOwner);
300	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
301	    }
302	
303	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
304	    @Transactional
305	    @Override
306	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
307	        Owner owner = this.clinicService.findOwnerById(ownerId);
308	        if (owner == null) {
309	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
310	        }
311	        this.clinicService.deleteOwner(owner);
312	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
313	    }
314	
315	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
316	    @Override
317	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
318	        Owner owner = this.clinicService.findOwnerById(ownerId);
319	        if (owner == null) {
320	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
321	        }
322	        HttpHeaders headers = new HttpHeaders();
323	        Pet pet = petMapper.toPet(petFieldsDto);
324	        owner.setId(ownerId);
325	        pet.setOwner(owner);
326	        pet.getType().setName(null);
327	        this.clinicService.savePet(pet);
328	        PetDto petDto = petMapper.toPetDto(pet);
329	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
330	            .buildAndExpand(pet.getId()).toUri());
331	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
332	    }
333	
334	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
335	    @Override
336	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
337	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
338	        if (currentOwner != null) {
339	            Pet currentPet = this.clinicService.findPetById(petId);
340	            if (currentPet != null) {
341	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
342	                currentPet.setName(petFieldsDto.getName());
343	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
344	                this.clinicService.savePet(currentPet);
345	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
346	            }
347	        }
348	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
349	    }
350	
351	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
352	    @Override
353	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
354	        HttpHeaders headers = new HttpHeaders();
355	        Visit visit = visitMapper.toVisit(visitFieldsDto);
356	        Pet pet = new Pet();
357	        pet.setId(petId);
358	        visit.setPet(pet);
359	        this.clinicService.saveVisit(visit);
360	        VisitDto visitDto = visitMapper.toVisitDto(visit);
361	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
362	            .buildAndExpand(visit.getId()).toUri());
363	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
364	    }
365	
366	
367	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
368	    @Override
369	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
370	        Owner owner = this.clinicService.findOwnerById(ownerId);
371	        if (owner != null) {
372	            Pet pet = owner.getPet(petId);
373	            if (pet != null) {
374	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
375	            }
376	        }
377	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
378	    }
379	}
